1	export type Cell = [number, number];
2	
3	const key = ([x, y]: Cell): string => `${x},${y}`;
4	
5	export function nextGeneration(cells: Cell[]): Cell[] {
6	  const liveSet = new Set(cells.map(key));
7	
8	  // Count how many live neighbours each candidate cell has, keeping the
9	  // candidate's coordinates alongside its count so no decoding is needed.
10	  const neighbours = new Map<string, { cell: Cell; count: number }>();
11	  for (const [x, y] of cells) {
12	    for (let dx = -1; dx <= 1; dx++) {
13	      for (let dy = -1; dy <= 1; dy++) {
14	        if (dx === 0 && dy === 0) continue;
15	        const cell: Cell = [x + dx, y + dy];
16	        const cellKey = key(cell);
17	        const entry = neighbours.get(cellKey) ?? { cell, count: 0 };
18	        entry.count++;
19	        neighbours.set(cellKey, entry);
20	      }
21	    }
22	  }
23	
24	  // A dead cell with exactly 3 live neighbours is born (reproduction);
25	  // a live cell with 2 or 3 live neighbours survives.
26	  const next: Cell[] = [];
27	  for (const { cell, count } of neighbours.values()) {
28	    const alive = liveSet.has(key(cell));
29	    if (count === 3 || (alive && count === 2)) {
30	      next.push(cell);
31	    }
32	  }
33	  return next;
34	}
